import{_ as t,o,c as r,a2 as a}from"./chunks/framework.il0noOp3.js";const g=JSON.parse('{"title":"AzGovViz methodology evaluation (AB#6448)","description":"","frontmatter":{},"headers":[],"relativePath":"design/azgovviz-methodology-evaluation.md","filePath":"design/azgovviz-methodology-evaluation.md"}'),n={name:"design/azgovviz-methodology-evaluation.md"};function i(s,e,d,c,l,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="azgovviz-methodology-evaluation-ab-6448" tabindex="-1">AzGovViz methodology evaluation (AB#6448) <a class="header-anchor" href="#azgovviz-methodology-evaluation-ab-6448" aria-label="Permalink to &quot;AzGovViz methodology evaluation (AB#6448)&quot;">​</a></h1><p><strong>Story AB#6448, Feature AB#6458, Epic AB#6454.</strong> Justifies the Cloud Governance report&#39;s structure (<code>Export-GovernanceReport.ps1</code>, AB#6459) against what AzGovViz — the tool the Epic&#39;s own description names as the source of this reporting gap — actually does. <strong>Out of scope: executing AzGovViz itself, and modifying any Azure resource. Scout is read-only</strong>, and this evaluation is a documentation exercise, not a code integration against the real tool.</p><p>Grounded in AzGovViz&#39;s published capabilities (verified 2026-08-01): <a href="https://github.com/Azure/Azure-Governance-Visualizer" target="_blank" rel="noreferrer">Azure/Azure-Governance-Visualizer</a> / <a href="https://github.com/JulianHayward/Azure-MG-Sub-Governance-Reporting" target="_blank" rel="noreferrer">JulianHayward/Azure-MG-Sub-Governance-Reporting</a> (the canonical, actively-maintained repo; several other GitHub results for &quot;AzGovViz&quot; are forks of the same project).</p><h2 id="what-azgovviz-is" tabindex="-1">What AzGovViz is <a class="header-anchor" href="#what-azgovviz-is" aria-label="Permalink to &quot;What AzGovViz is&quot;">​</a></h2><p>A PowerShell script that walks a Management Group hierarchy top-down via the ARM, Storage, and Microsoft Graph APIs, capturing Azure Policy, RBAC, and related governance data, and rendering it into a single-page HTML report plus CSV/Markdown/JSON exports. It is exclusively read-only.</p><h2 id="what-azgovviz-does-that-scout-does-not" tabindex="-1">What AzGovViz does that Scout does not <a class="header-anchor" href="#what-azgovviz-does-that-scout-does-not" aria-label="Permalink to &quot;What AzGovViz does that Scout does not&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>AzGovViz</th><th>Scout today</th><th>Verdict</th></tr></thead><tbody><tr><td><strong>Management-group hierarchy tree visualization</strong> with per-scope subscription/assignment/role counts</td><td>Yes — a rendered <code>HierarchyMap</code></td><td>No — <code>governance.managementGroups</code> is collected but never rendered as a tree; only flat counts</td><td><strong>Worth adopting eventually, out of scope for this Feature.</strong> AB#6459&#39;s AC calls for a radar chart and heatmap specifically, not a hierarchy visualization; adding a third, unrelated chart type here would scope-creep the Feature. Flagged for a future story if a hierarchy view is wanted.</td></tr><tr><td><strong>Microsoft Entra service-principal inventory with secret/certificate expiry tracking</strong>, group-membership resolution, user-type classification</td><td>Yes</td><td>No — Scout has no Entra/Graph collector for this at all</td><td><strong>Confirmed real gap, rejected for THIS Feature.</strong> This independently corroborates <code>docs/frameworks/cloud-governance-question-set.md</code>&#39;s <code>CGOV-SC-03</code> finding (identity governance monitoring is unobservable from Scout&#39;s current data) — the same conclusion reached two different ways. Closing it needs a new Microsoft Graph collector, which is collection work, not reporting work; out of scope here, worth a future collector story.</td></tr><tr><td><strong>CAF naming-convention alignment checks</strong></td><td>Yes</td><td>No</td><td><strong>Rejected for this Feature</strong> — a naming-convention linter is a distinct rule-authoring exercise unrelated to the governance maturity report; not blocking anything AB#6459 asks for.</td></tr><tr><td><strong>Orphaned policy/role definition detection</strong> (<code>DefinitionInsights</code>)</td><td>Yes</td><td>Partial — Scout reads assignments, not orphaned <em>definitions</em></td><td><strong>Rejected for this Feature</strong>, same reasoning as naming checks — a distinct rule, not a reporting-structure decision.</td></tr><tr><td><strong>Markdown/Azure DevOps Wiki output with Mermaid diagrams</strong></td><td>Yes</td><td>No</td><td><strong>Rejected.</strong> Scout&#39;s live renderer contract is React plus JSON data outputs. Use the React page&#39;s Markdown export rather than adding another standalone renderer.</td></tr></tbody></table><h2 id="what-scout-already-does-that-azgovviz-explicitly-does-not" tabindex="-1">What Scout already does that AzGovViz explicitly does not <a class="header-anchor" href="#what-scout-already-does-that-azgovviz-explicitly-does-not" aria-label="Permalink to &quot;What Scout already does that AzGovViz explicitly does not&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Scout</th><th>AzGovViz</th><th>Why it matters here</th></tr></thead><tbody><tr><td><strong>Scoring / rating</strong></td><td>Yes — <code>Get-Score</code> produces weighted Pass/Partial/Fail percentages per area and framework; this Feature adds a 1-10 domain maturity number on top</td><td><strong>Explicitly does not.</strong> AzGovViz&#39;s own documentation states it &quot;focuses on enumeration, enrichment, and connection of governance artifacts rather than scoring posture.&quot;</td><td>This is Scout&#39;s actual differentiator and the entire reason AB#6459 exists — AzGovViz was never trying to solve &quot;how mature is this tenant&#39;s governance,&quot; only &quot;what governance artifacts exist and how do they connect.&quot; The Cloud Governance report is not a reimplementation of AzGovViz; it is the scoring layer AzGovViz deliberately does not provide.</td></tr><tr><td><strong>Multi-framework rule engine</strong> (CAF design areas, WAF pillars, regulatory-compliance initiatives, SMART migration readiness, cross-resource correlation, and now CAF Govern)</td><td>Yes — one engine, many rule files</td><td>No — governance-artifact enumeration only, no framework mapping</td><td>Confirms the report&#39;s shape (reuse <code>Get-Score</code>&#39;s existing Areas/Frameworks output, add a relabeling function) is the right fit for how Scout already works, rather than a bespoke governance-only pipeline.</td></tr><tr><td><strong>Fully offline / strict-CSP HTML output</strong></td><td>Yes — <code>Export-EChartsDashboard.ps1</code>&#39;s vendored Apache ECharts v5.6.0 build, acquired once at authoring time, never fetched at render time</td><td><strong>No.</strong> AzGovViz&#39;s HTML single-page report loads CSS from a CDN at render/view time.</td><td><strong>This is the decisive rejection.</strong> AB#6459&#39;s AC explicitly requires &quot;a strict CSP and offline operation... no CDN, no external fonts.&quot; AzGovViz&#39;s own report artifact would fail that requirement outright. <code>Export-GovernanceReport.ps1</code> deliberately reuses the same vendored-library mechanism <code>Export-EChartsDashboard.ps1</code> already built and tested (<code>$Script:ScoutEChartsLibJs</code>), rather than following AzGovViz&#39;s CDN-based approach or introducing a second charting dependency.</td></tr><tr><td><strong>Multiple renderer targets from one scored object</strong> (historical design)</td><td>Yes</td><td>No — fixed HTML/CSV/Markdown/JSON</td><td>The legacy targets are now held. New document exports must derive from the React report model rather than a parallel one-off pipeline.</td></tr></tbody></table><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>Adopted:</strong> the report-as-scoring-layer positioning (Scout&#39;s differentiator over AzGovViz), the offline/vendored-library rendering approach already proven in <code>Export-EChartsDashboard.ps1</code>, and reuse of the existing multi-framework rule engine rather than a bespoke governance-only code path.</p><p><strong>Deliberately rejected for this Feature</strong> (real capabilities, wrong scope): hierarchy tree visualization, Entra service-principal/secret-expiry tracking, CAF naming-convention checks, orphaned-definition detection, and Markdown/Wiki output. Each is a legitimate feature; none of them is what AB#6459&#39;s AC (1-10 domain score, radar, heatmap, offline HTML/PDF) asks for, and bundling them in would have turned a reporting story into a collector-and-rule-authoring program. The Entra/secret-expiry gap in particular is tracked as a known, real limitation via <code>CGOV-SC-03</code> in <code>src/assess/rules/caf.govern.sc.yaml</code> — visible in every governance report as &quot;Not assessed,&quot; not silently absent.</p>',12)])])}const p=t(n,[["render",i]]);export{g as __pageData,p as default};
